INSERT INTO `form_point_ext` VALUES (1,NULL,'Tiêu chí 1: Đánh giá về ý thức tham gia học tập',NULL,'header',NULL),(2,1.1,'Ý thức và thái độ trong học tập:',NULL,'row',1),(3,NULL,'Đi học đầy đủ, đúng giờ, nghiêm túc trong giờ học, giờ\r\nthực hành',3,'row',1),(4,1.2,'Kết quả học tập trong kỳ học',NULL,'row',1),(5,NULL,'+ Có kết quả học tập xếp loại Xuất sắc',10,'row',1),(6,NULL,'+ Có kết quả học tập đạt loại Giỏi',8,'row',1),(7,NULL,'+ Có kết quả học tập đạt loại Khá',6,'row',1),(8,NULL,'+ Có kết quả học tập đạt loại Trung bình',4,'row',1),(9,NULL,'+ Có kết quả học tập đạt loại dưới Trung bình',0,'row',1),(10,NULL,'- Học lại (phần lý thuyết/ thực hành)',-1,'row',1),(11,1.3,'Ý thức chấp hành tốt nội quy về các kỳ thi',4,'row',1),(12,NULL,'Sinh viên bị trừ điểm trong các trường hợp/1 lần vi phạm:',NULL,'row',1),(13,NULL,'+ Không đủ điều kiện dự thi/bị cấm thi cho mỗi học phần (lý thuyết/ thực hành)',-2,'row',1),(14,NULL,'+ Bị lập biên bản khiển trách khi thi kết thúc học phần',-2,'row',1),(15,NULL,'+ Bị lập biên bản cảnh cáo khi thi kết thúc học phần',-3,'row',1),(16,NULL,'+ Bị lập biên bản đình chỉ khi thi kết thúc học phần',-4,'row',1),(17,1.4,'Ý thức và thái độ tham gia các hoạt động ngoại khóa, các sự kiện liên quan đến nghiên cứu khoa học, học thuật, chuyên môn, Câu lạc bộ (0,5 điểm/1 sự kiện, hoạt\r\nđộng tham gia, tổng điểm không vượt quá 2 điểm)',2,'row',1),(18,1.5,'Tinh thần vượt khó, phấn đấu vươn lên trong học tập (có ĐTBCTL học kỳ sau lớn hơn học kỳ trước đó; đối với sinh viên năm thứ nhất, học kỳ 1 không có điểm dưới\r\n2,5)',1,'row',1),(19,NULL,'Mức điểm tối đa Tiêu chí 1',20,'total',1),(20,NULL,'Tiêu chí 2: Đánh giá về ý thức chấp hành nội quy, quy chế, quy định của Học viện',NULL,'header',NULL),(21,2.1,'Thực hiện nghiêm túc các nội quy, quy chế, các quy định hiện hành trong Học viện.',15,'row',20),(22,NULL,'- Sinh viên bị trừ điểm trong các trường hợp:',NULL,'row',20),(23,NULL,'+ Không đóng học phí theo quy định',-15,'row',20),(24,NULL,'+ Không thực hiện quy định về công tác ngoại trú, nội\r\ntrú.',-5,'row',20),(25,2.2,'- Thực hiện nghiệp túc các buổi họp lớp/ sinh hoạt đoàn thể do Học viện/Khoa/Viện, CVHT, Lớp/Chi đoàn tổ chức (tùy thuộc vào số buổi tổ chức sinh hoạt, họp)',5,'row',20),(26,2.2,'- Vắng 01 buổi hợp lớp/ sinh hoạt đoàn thể (không lý do)',-1,'row',20),(27,2.3,'- Tham gia các buổi hội thảo việc làm, định hướng nghề nghiệp do Học viện tổ chức (1 điểm/1 sự kiện tham gia, tổng điểm không vượt quá 5 điểm)',5,'row',20),(28,2.3,'- Vắng 01 buổi',-2,'row',20),(29,NULL,'Mức điểm tối đa Tiêu chí 2',25,'total',20),(30,NULL,'Tiêu chí 3. Đánh giá về ý thức và kết quả tham gia hoạt động chính trị- xã hội, văn hóa, văn nghệ, thể thao, phòng chống tội phạm và các tệ nạn xã hội',NULL,'header',NULL),(31,3.1,'Tham gia đầy đủ các hoạt động chính trị, xã hội, các hoạt động văn hóa, văn nghệ, thể thao, phong trào tình nguyện, các buổi sinh hoạt chuyên đề do Học viện,\r\nlớp/chi đoàn, địa phương nơi cư trú tổ chức (2 điểm/1 hoạt động, tổng điểm không vượt quá 10 điểm)',10,'row',30),(32,3.2,'Tham gia công tác xã hội như: hiến máu nhân đạo, ủng hộ người nghèo gặp thiên tai lũ lụt và các công tác xã hội khác (1 điểm/1 hoạt động tham gia, tổng điểm không vượt quá 4 điểm)',4,'row',30),(33,3.3,'Tuyên truyền tích cực hình ảnh về Trường/Khoa trên các trang mạng xã hội (1 điểm/1 hoạt động, tổng điểm không vượt quá 3 điểm)',3,'row',30),(34,3.4,'Tích cực tham gia các hoạt động phòng, chống tội phạm, các tệ nạn xã hội, phát hiện và báo cáo kịp thời những hành vi có liên quan đến ma túy, các tệ nạn xã hội khác',3,'row',30),(35,3.5,'Đưa các thông tin sai lệch, thông tin chưa được kiểm chứng, đăng bình luận không chính xác, thiếu tích cực về Học viện/ Khoa/ ngành đang học.',-10,'row',30),(36,NULL,'Mức điểm tối đa Tiêu chí 3',20,'total',30),(37,NULL,'Tiêu chí 4. Đánh giá ý thức công dân trong quan hệ cộng đồng',NULL,'header',NULL),(38,4.1,'Chấp hành nghiêm chỉnh chủ trương của Đảng, chính sách, pháp luật của Nhà nước, Học viện và của địa phương nơi cư trú',8,'row',37),(39,4.2,'Tích cực tham gia tuyên truyền chủ trương của Đảng, chính sách, pháp luật của Nhà nước, Học viện và quy định của địa phương nơi cư trú; có ý thức thực hiện giữ gìn vệ sinh chung',5,'row',37),(40,4.3,'Có mối quan hệ đúng mực với Thầy/ Cô, cán bộ, nhân viên Học viện',5,'row',37),(41,4.4,'Có mối quan hệ tốt với bạn bè trong lớp và mọi người\r\nxung quanh; có tinh thần đoàn kết, chia sẻ, giúp đỡ nhau\r\ntrong học tập và các vấn đề khác trong cộng đồng',5,'row',37),(42,4.5,'Được biểu dương khen thưởng trong các hoạt động liên quan đến ý thức công dân trong quan hệ cộng đồng',2,'row',37),(43,4.6,'Vi phạm an ninh, trật tự xã hội; an toàn giao thông (có giấy báo của các cơ quan hữu quan)',-5,'row',37),(44,NULL,'Mức điểm tối đa Tiêu chí 4',25,'total',37),(45,NULL,'Tiêu chí 5. Đánh giá về ý thức và kết quả tham gia phụ trách lớp, các đoàn thể trong nhà trường, thành tích đặc biệt trong học tập và rèn luyện',NULL,'header',NULL),(46,5.1,'Sinh viên được Học viện phân công làm lớp trưởng, lớp phó; bí thư, phó bí thư chi đoàn, BCH đoàn Học viện/khoa; BCH Hội sinh viên Học viện/khoa; chủ nhiệm, phó chủ nhiệm các các Câu lạc bộ, đội nhóm trực thuộc Học viện/khoa được tập thể sinh viên và đơn vị quản lý ghi nhận hoàn thành nhiệm vụ.',4,'row',45),(47,5.2,'Thành viên tham gia các Câu lạc bộ, đội nhóm trực thuộc Học viện /khoa được tập thể sinh viên và đơn vị quản lý ghi nhận hoàn thành tốt nhiệm vụ; sinh viên tham gia tổ chức các chương trình, là cộng tác viên tham gia tích cực vào các hoạt động chung cấp Học viện, khoa.',3,'row',45),(48,5.3,'Sinh viên đạt thành tích đặc biệt trong học tập, rèn luyện:\n-Đạt giải thường trong nghiên cứu khoa học, các cuộc thi Olympic các cấp.\n- Đạt huy chương, giấy khen, giải thưởng các cấp về văn hóa, văn nghệ, thể thao, phòng chống các tệ nạn xã hội, hoạt động vì cộng đồng...',3,'row',45),(51,NULL,'Mức điểm tối đa Tiêu chí 5',10,'total',45);
